// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Genel ek sorular: Edebiyat kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: Türk edebiyatı: İslamiyet öncesi, Divan ve Halk edebiyatı | Türk edebiyatı: Tanzimat'tan Cumhuriyet'e yazarlar ve eserler | Dünya edebiyatı: yazarlar, eserler, akımlar | Edebî türler, şiir bilgisi, söz sanatları ve anlatım teknikleri) (kolay).
const ozLiterature5Kolay = <(String, String, List<String>, String)>[
  ('Orhan Veli, Oktay Rifat ve Melih Cevdet\'in şiirlerini bir araya getiren ve 1941\'de yayımlanan ortak kitabın adı nedir?', 'Garip', ['Sesler', 'Mavi', 'Yedi Meşale'], '1941\'de yayımlanan Garip, üç şairin ortak kitabıdır ve önsözüyle Türk şiirinde yeni bir dönemin bildirisi sayılır.'),
  ('Garip kitabının önsözünde şiirden atılması gerektiği savunulan unsurlar hangi seçenekte doğru verilmiştir?', 'Vezin, kafiye ve benzetme gibi süsler', ['Konuşma dili ve gündelik hayattan sözcükler', 'Sıradan insan ve günlük olaylar', 'Mizah, ironi ve şaşırtıcı sonlar'], 'Orhan Veli önsözde ölçüyü, uyağı ve teşbih, istiare gibi söz sanatlarını şiirin dışına atmayı önermiştir.'),
  ('\'Hiçbir şeyden çekmedi dünyada / Nasırından çektiği kadar\' dizeleriyle başlayan Kitabe-i Seng-i Mezar şiirinde sözü edilen kişi kimdir?', 'Süleyman Efendi', ['Ahmet Ağa', 'Kâzım Bey', 'Abdülkadir Efendi'], 'Orhan Veli\'nin bu şiiri, sıradan bir memur olan Süleyman Efendi\'nin mezar taşı yazısı biçimindedir ve Garip\'in \'küçük adam\' ilgisini gösterir.'),
  ('\'Bedava yaşıyoruz, bedava; / Hava bedava, bulut bedava\' dizelerindeki yalın söyleyiş, gündelik dil ve hafif ironi en çok hangi şiir anlayışına özgüdür?', 'Garip', ['Beş Hececiler', 'Servet-i Fünun', 'Hisarcılar'], 'Ölçüsüz, uyaksız, konuşma diline yakın ve ironik söyleyiş Garip akımının belirgin özelliklerindendir; dizeler Orhan Veli\'nin \'Bedava\' şiirindendir.'),
  ('Garip şairlerinin şiirlerinde kahraman olarak sıkça seçtiği insan tipi hangisidir?', 'Gündelik hayatı içinde sıradan, adsız insan', ['Destan kahramanı olan savaşçı ve cesur bir akıncı', 'Saray çevresinde yaşayan seçkin aristokrat', 'Tasavvuf yolunda ilerleyen bir derviş'], 'Garip şiiri büyük kahramanlar yerine sokaktaki \'küçük adamı\', onun dertlerini ve sevinçlerini konu edinmiştir.'),
  ('\'İstanbul\'u dinliyorum, gözlerim kapalı\' dizesiyle başlayan ünlü şiir hangi şaire aittir?', 'Orhan Veli Kanık', ['Yahya Kemal Beyatlı', 'Ahmet Hamdi Tanpınar', 'Necip Fazıl Kısakürek'], '\'İstanbul\'u Dinliyorum\', Orhan Veli\'nin şehri seslerle betimlediği ünlü şiiridir.'),
  ('Nazım Hikmet\'in Kurtuluş Savaşı\'nı halkın gözünden anlattığı destan niteliğindeki uzun şiiri hangisidir?', 'Kuvâyi Milliye', ['Taranta Babu\'ya Mektuplar', 'Jokond ile Si-Ya-U', 'Benerci Kendini Niçin Öldürdü'], 'Kuvâyi Milliye (Kurtuluş Savaşı Destanı), Memleketimden İnsan Manzaraları\'nın bir bölümü olarak da bilinen, Millî Mücadele\'yi anlatan uzun şiirdir.'),
  ('Nazım Hikmet\'in 15. yüzyılda bir halk ayaklanmasına önderlik eden düşünürü konu alan 1936 tarihli destanı hangisidir?', 'Şeyh Bedreddin Destanı', ['Ferhad ile Şirin', 'Sesini Kaybeden Şehir', 'Kafatası'], 'Simavne Kadısı Oğlu Şeyh Bedreddin Destanı, Nazım\'ın Börklüce Mustafa ayaklanmasını da işlediği önemli bir eseridir.'),
  ('\'Yaşamak bir ağaç gibi tek ve hür / ve bir orman gibi kardeşçesine\' dizeleri hangi şairin \'Davet\' şiirindendir?', 'Nazım Hikmet', ['Ahmed Arif', 'Attila İlhan', 'Hasan Hüseyin Korkmazgil'], 'Bu dizeler Nazım Hikmet\'in \'Davet\' şiirinden olup bireysel özgürlükle toplumsal dayanışmayı bir arada savunur.'),
